"""policy.ini (docs/policy.md)."""

import re

from logkeep import streams
from logkeep.errors import DataError

BUILTIN = {"max_size": None, "max_age": None, "naming": "numbered", "offset": 0,
           "compress_after": 1, "keep": 5, "keep_days": None}
_A = re.ASCII


def _bad(msg):
    return DataError("policy", f"policy.ini: {msg}")


def _size(v):
    if v == "off":
        return None
    m = re.fullmatch(r"([0-9]+)([KMGkmg]?)", v, _A)
    if not m:
        raise ValueError
    return int(m[1]) * {"": 1, "k": 1024, "m": 1024**2, "g": 1024**3}[m[2].lower()]


def _age(v):
    """Seconds, or None for off."""
    if v == "off":
        return None
    m = re.fullmatch(r"([0-9]+)([mhd])", v, _A)
    if not m:
        raise ValueError
    return int(m[1]) * {"m": 60, "h": 3600, "d": 86400}[m[2]]


def _naming(v):
    if v not in ("numbered", "dated"):
        raise ValueError
    return v


def _offset(v):
    m = re.fullmatch(r"([+-])([0-9]{2}):([0-9]{2})", v, _A)
    if not m or int(m[2]) > 23 or int(m[3]) > 59:
        raise ValueError
    s = int(m[2]) * 3600 + int(m[3]) * 60
    return -s if m[1] == "-" else s


def _int(minimum):
    def f(v):
        if not re.fullmatch(r"[0-9]+", v, _A) or int(v) < minimum:
            raise ValueError
        return int(v)
    return f


def _keep_days(v):
    return None if v == "off" else _int(1)(v)


PARSERS = {"max_size": _size, "max_age": _age, "naming": _naming, "offset": _offset,
           "compress_after": _int(0), "keep": _int(1), "keep_days": _keep_days}


class Policy:
    def __init__(self, defaults=None, sections=None):
        self.defaults = defaults or {}
        self.sections = sections or {}

    def names(self):
        return set(self.sections)

    def get(self, stream):
        s = dict(BUILTIN)
        s.update(self.defaults)
        s.update(self.sections.get(stream, {}))
        return s


def load(path) -> Policy:
    if not path.exists():
        return Policy()
    try:
        text = path.read_text(encoding="utf-8")
    except (OSError, UnicodeDecodeError) as e:
        raise _bad(str(e)) from None
    defaults = None
    sections = {}
    cur = None
    for raw in text.splitlines():
        line = raw.strip()
        if not line or line[0] in "#;":
            continue
        if line.startswith("["):
            if not line.endswith("]"):
                raise _bad(f"bad line: {line}")
            title = line[1:-1]
            if title == "defaults":
                if defaults is not None:
                    raise _bad("section given twice")
                defaults = {}
                cur = defaults
            elif title.startswith("stream ") and streams.valid(title[7:]):
                name = title[7:]
                if name in sections:
                    raise _bad("section given twice")
                sections[name] = {}
                cur = sections[name]
            else:
                raise _bad(f"unknown section: {title}")
            continue
        if cur is None or "=" not in line:
            raise _bad(f"bad line: {line}")
        key, _, value = line.partition("=")
        key, value = key.strip(), value.strip()
        if key not in PARSERS:
            raise _bad(f"unknown key: {key}")
        if key in cur:
            raise _bad(f"key given twice: {key}")
        try:
            cur[key] = PARSERS[key](value)
        except ValueError:
            raise _bad(f"bad value for {key}: {value}") from None
    return Policy(defaults, sections)
