"""rotate (docs/rotate.md)."""

import gzip
import os
import re
from datetime import date, datetime, timedelta, timezone

from logkeep import dates, policy as policy_mod, state as state_mod, streams
from logkeep.errors import DataError, Refused

_A = re.ASCII
_ISO = re.compile(r"([0-9]{4}-[0-9]{2}-[0-9]{2})T([0-9]{2}:[0-9]{2}:[0-9]{2})(?:[.,]([0-9]+))?"
                  r"(Z|[+-][0-9]{2}(?::?[0-9]{2})?)\Z", _A)
_OLD = re.compile(r"[0-9]{4}-[0-9]{2}-[0-9]{2} [0-9]{2}:[0-9]{2}:[0-9]{2}\Z", _A)


def parse_iso(text):
    """ISO 8601 time with Z or an offset -> aware datetime, or None."""
    m = _ISO.match(text)
    if not m:
        return None
    frac = (m[3] or "0")[:6].ljust(6, "0")
    z = m[4]
    if z == "Z":
        z = "+00:00"
    elif ":" not in z:
        z = z[:3] + ":" + (z[3:] or "00")
    try:
        return datetime.fromisoformat(f"{m[1]}T{m[2]}.{frac}{z}")
    except ValueError:
        return None


def parse_state_time(v):
    if not isinstance(v, str):
        return None
    if _OLD.match(v):
        try:
            return datetime.fromisoformat(v).replace(tzinfo=timezone.utc)
        except ValueError:
            return None
    return parse_iso(v)


def _state_error(msg):
    return DataError("state", f"state.json: {msg}")


def validate_entry(name, entry):
    if "opened" in entry and parse_state_time(entry["opened"]) is None:
        raise _state_error(f"{name}: bad opened")
    if "archives" in entry:
        a = entry["archives"]
        if not isinstance(a, dict):
            raise _state_error(f"{name}: archives is not an object")
        for k, v in a.items():
            if parse_state_time(v) is None:
                raise _state_error(f"{name}: bad time for {k}")
    if "rotations" in entry:
        r = entry["rotations"]
        if not isinstance(r, int) or isinstance(r, bool) or r < 0:
            raise _state_error(f"{name}: bad rotations")


class Archive:
    def __init__(self, name, key, gz, new=False):
        self.name = name      # name before the run (None for the new one)
        self.key = key
        self.gz = gz
        self.new = new
        self.final = None
        self.compress = False


def find_archives(logs, name, naming):
    out = []
    if not logs.is_dir():
        return out
    n = re.escape(name)
    if naming == "numbered":
        rx = re.compile(rf"{n}\.log\.([1-9][0-9]*)(\.gz)?\Z", _A)
    else:
        rx = re.compile(rf"{n}\.log\.([0-9]{{4}}-[0-9]{{2}}-[0-9]{{2}})(?:\.([2-9]|[1-9][0-9]+))?(\.gz)?\Z", _A)
    seen = {}
    for p in logs.iterdir():
        m = rx.match(p.name)
        if not m or not p.is_file():
            continue
        if naming == "numbered":
            key, gz = (int(m[1]),), bool(m[2])
        else:
            try:
                date.fromisoformat(m[1])
            except ValueError:
                continue
            key, gz = (m[1], int(m[2]) if m[2] else 1), bool(m[3])
        if key in seen:
            raise DataError("archives", f"{name}: two archives in the same place")
        seen[key] = Archive(p.name, key, gz)
    return [seen[k] for k in sorted(seen)]


def _dated_name(name, key, gz):
    day, k = key
    return f"{name}.log.{day}" + (f".{k}" if k > 1 else "") + (".gz" if gz else "")


def first_line_time(path):
    try:
        with open(path, "rb") as f:
            line = f.readline()
    except OSError:
        return None
    line = line.rstrip(b"\r\n")
    if b" " not in line:
        return None
    return parse_iso(line.split(b" ", 1)[0].decode("utf-8", "replace"))


def run(ctx, requested, dry_run, force):
    pol = policy_mod.load(ctx.policy_path)
    st = ctx.state
    logs = streams.logs_dir(ctx.data)
    existing = set(streams.active(ctx.data)) | pol.names()
    for name, entry in st["streams"].items():
        if name in existing:
            validate_entry(name, entry)
    if requested:
        names = sorted(set(requested))
        for n in names:
            if n not in existing:
                raise Refused("unknown-stream", f"no stream {n}")
    else:
        names = sorted(existing)

    plans = []
    for name in names:
        s = pol.get(name)
        plans.append((name, s, find_archives(logs, name, s["naming"])))

    now = ctx.now
    out = []
    ops = []   # (stream result) for the file work
    new_state = {}
    t_rot = t_rem = t_cmp = 0
    for name, s, archives in plans:
        entry = st["streams"].get(name, {})
        times = entry.get("archives", {})
        active = streams.log_path(ctx.data, name)
        reason = None
        if not active.is_file():
            what = "no log"
        else:
            size = active.stat().st_size
            if size == 0:
                what = "empty"
            elif force:
                what, reason = "rotate (forced)", True
            elif s["max_size"] is not None and size >= s["max_size"]:
                what, reason = "rotate (size)", True
            else:
                what = "not due"
                if s["max_age"] is not None:
                    op = parse_state_time(entry["opened"]) if "opened" in entry else None
                    if op is None:
                        op = first_line_time(active)
                    if op is not None and (now - op).total_seconds() >= s["max_age"]:
                        what, reason = "rotate (age)", True
        rotated = bool(reason)
        out.append(f"{name}: {what}")

        items = list(archives)
        if rotated:
            if s["naming"] == "numbered":
                new = Archive(None, (0,), False, new=True)
            else:
                tz = timezone(timedelta(seconds=s["offset"]))
                day = now.astimezone(tz).date().isoformat()
                ks = [a.key[1] for a in archives if a.key[0] == day]
                new = Archive(None, (day, max(ks) + 1 if ks else 1), False, new=True)
            items.append(new)
            items.sort(key=lambda a: a.key if s["naming"] == "dated" else a.key)
        if s["naming"] == "numbered":
            if rotated:
                items = [new] + archives
        else:
            items.sort(key=lambda a: a.key, reverse=True)
        # items: newest first. dated sorted newest first above; numbered: N ascending = newest first
        removed, kept = [], []
        for pos, a in enumerate(items, 1):
            drop = pos > s["keep"]
            if not drop and s["keep_days"] is not None and a.name in times:
                t = parse_state_time(times[a.name])
                if (now - t).total_seconds() >= s["keep_days"] * 86400:
                    drop = True
            (removed if drop else kept).append(a)
        for pos, a in enumerate(kept, 1):
            a.compress = pos > s["compress_after"] and not a.gz
            gz = a.gz or a.compress
            if s["naming"] == "numbered":
                a.final = f"{name}.log.{pos}" + (".gz" if gz else "")
            else:
                a.final = _dated_name(name, a.key, gz)
            if a.compress:
                t_cmp += 1
            if a.new:
                out.append(f"  new {a.final}")
            elif a.final != a.name:
                out.append(f"  {a.final} <- {a.name}")
            else:
                out.append(f"  {a.name}")
        for a in removed:
            out.append(f"remove {a.name}")
        t_rot += rotated
        t_rem += len(removed)

        ne = {}
        if "opened" in entry or rotated:
            ne["opened"] = ctx.stamp if rotated else entry["opened"]
        ne["rotations"] = entry.get("rotations", 0) + (1 if rotated else 0)
        arch = {}
        for a in kept:
            if a.new:
                arch[a.final] = ctx.stamp
            elif a.name in times:
                arch[a.final] = times[a.name]
        ne["archives"] = arch
        new_state[name] = ne
        ops.append((name, active, kept, removed))

    out.append(f"{t_rot} rotated, {t_rem} removed, {t_cmp} compressed")
    if dry_run:
        out.append("dry run: nothing written")
        return out

    # file work: stage every changed file under a temporary name, then place them
    staged = []
    counter = 0
    for name, active, kept, removed in ops:
        for a in removed:
            os.remove(logs / a.name)
        for a in kept:
            if a.new:
                src = active
            elif a.final == a.name:
                continue
            else:
                src = logs / a.name
            counter += 1
            tmp = logs / f".logkeep-tmp-{counter}"
            if a.compress:
                data = src.read_bytes()
                tmp.write_bytes(gzip.compress(data, mtime=0))
                if a.new:
                    active.write_bytes(b"")
                else:
                    os.remove(src)
            elif a.new:
                os.rename(src, tmp)
                active.write_bytes(b"")
            else:
                os.rename(src, tmp)
            staged.append((tmp, logs / a.final))
    for tmp, final in staged:
        os.replace(tmp, final)
    st["streams"].update(new_state)
    state_mod.save(ctx.state_path, st)
    return out
